  "facts": [
    {
      "fact_type": null,
      "fact_text": {
        "text": "byte takes one byte of memory and can store values from -128 to 127.",
        "refs": ["Q0001"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "short takes two bytes of memory and can store values up to 32,000.",
