    {
      "fact_type": null,
      "fact_text": {
        "text": "int (integer) takes four bytes of memory and can store values up to two billion.",
        "refs": ["Q0001"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "long takes eight bytes of memory and can store even larger numbers.",
        "refs": ["Q0001"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "float takes four bytes of memory and is used for numbers with a decimal point.",
        "refs": ["Q0002"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "double takes eight bytes of memory and is used for numbers with a decimal point, allowing larger values than float.",
        "refs": ["Q0002"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "char takes two bytes of memory and stores a single character, supporting international letters.",
        "refs": ["Q0002"]
      }
    },
    {
      "fact_type": null,
      "fact_text": {
        "text": "boolean stores true or false values.",
